[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ sosa:hasFeatureOfInterest [ ns1:name "Eurostat NUTS region indicator set" ] ;
                    sosa:madeBySensor [ ns1:encodingType "application/json" ;
                            ns1:metadata "Source model output represented from examples/eurostat nuts regions.qgz" ;
                            ns1:name "Swedish Digital Twin fisheries simulation model" ] ;
                    sosa:observedProperty [ skos:definition "https://w3id.org/ogc/hosted/seadots/swedish-dt#fisheriesSimulationState" ;
                            ns1:name "Swedish DT fisheries simulation state" ] ;
                    ns1:description "Whitespace-delimited simulation rows from the Swedish Digital Twin fisheries model." ;
                    ns1:name "Swedish DT Eurostat NUTS regions simulation output" ;
                    ns1:observationType "http://www.opengis.net/def/observationType/OGC-OM/2.0/OM_ComplexObservation" ;
                    ns1:unitOfMeasurement [ skos:definition "https://qudt.org/vocab/unit/UNITLESS" ;
                            ns1:name "model output bundle" ;
                            ns1:symbol "1" ] ] ;
            sh:resultMessage "Value is not of Node Kind sh:IRI" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:NodeKindConstraintComponent ;
            sh:sourceShape [ sh:nodeKind sh:IRI ;
                    sh:path sosa:observedProperty ] ;
            sh:value [ skos:definition "https://w3id.org/ogc/hosted/seadots/swedish-dt#fisheriesSimulationState" ;
                    ns1:name "Swedish DT fisheries simulation state" ] ] .

@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix ns1: <https://w3id.org/ogc/hosted/seadots/swedish-dt#> .
@prefix ns2: <http://www.opengis.net/def/ont/sensorthings/> .
@prefix schema: <https://schema.org/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ ns2:Datastream [ sosa:hasFeatureOfInterest [ ns1:name "Eurostat NUTS region indicator set" ] ;
                            sosa:madeBySensor [ ns1:encodingType "application/json" ;
                                    ns1:metadata "Source model output represented from examples/eurostat nuts regions.qgz" ;
                                    ns1:name "Swedish Digital Twin fisheries simulation model" ] ;
                            sosa:observedProperty [ skos:definition "https://w3id.org/ogc/hosted/seadots/swedish-dt#fisheriesSimulationState" ;
                                    ns1:name "Swedish DT fisheries simulation state" ] ;
                            ns1:description "Whitespace-delimited simulation rows from the Swedish Digital Twin fisheries model." ;
                            ns1:name "Swedish DT Eurostat NUTS regions simulation output" ;
                            ns1:observationType "http://www.opengis.net/def/observationType/OGC-OM/2.0/OM_ComplexObservation" ;
                            ns1:unitOfMeasurement [ skos:definition "https://qudt.org/vocab/unit/UNITLESS" ;
                                    ns1:name "model output bundle" ;
                                    ns1:symbol "1" ] ] ;
                    sosa:hasFeatureOfInterest [ ns1:description "Approximate Swedish case-region footprint spanning the northern Baltic/Bothnian Sea case waters southward to and including Gotland Island. The source table stores region membership as nuts_region_01 ... nuts_region_17 indicator columns; this geometry is an example footprint for the case region, not an authoritative Eurostat NUTS boundary." ;
                            ns1:encodingType "application/geo+json" ;
                            ns1:feature <file:///github/workspace/swedish-dt-case-region-north-to-gotland> ;
                            ns1:name "Swedish DT case region - northern Baltic to Gotland" ] ;
                    sosa:hasResult [ ns1:B_herring_tot 250000 ;
                            ns1:K_herring_reg_inc 1 ;
                            ns1:SV_fishing_radius 5 ;
                            ns1:SV_herring_market "fish meal" ;
                            ns1:TAC_herring_Sweden_impl 1 ;
                            ns1:TAC_herring_est_error 6.5e-01 ;
                            ns1:TAC_herring_inc_SV 1 ;
                            ns1:TAC_herring_share_sv 9.3e-02 ;
                            ns1:TAC_herring_type 0 ;
                            ns1:TAC_share_B_herring 3e-01 ;
                            ns1:VA_LV_All 4.316705e+04 ;
                            ns1:VA_SV_All 2.068744e+02 ;
                            ns1:catch_herring_LV_All 2.306167e+05 ;
                            ns1:catch_herring_SV_All 1.458718e+03 ;
                            ns1:catch_sprat_LV_All 2.888209e+05 ;
                            ns1:catch_sprat_SV_All 1.116481e+03 ;
                            ns1:current_TAC_herring 5.666949e+04 ;
                            ns1:current_herring_season "Evenly distributed" ;
                            ns1:current_management_season "No closure" ;
                            ns1:current_month 6 ;
                            ns1:current_year 1 ;
                            ns1:even_dispersal_rate 8e-02 ;
                            ns1:fishing_algorithm "profit maximisation" ;
                            ns1:fuel_consumption_LV 0 ;
                            ns1:fuel_consumption_SV 0 ;
                            ns1:fuel_price 0 ;
                            ns1:herring_price_fish_meal 2.41e+00 ;
                            ns1:herring_price_human_cons 1.125e+01 ;
                            ns1:landing-value_sprat_LV 6.960583e+05 ;
                            ns1:landing_value_herring_LV 5.557862e+05 ;
                            ns1:landing_value_herring_SV 3.515511e+03 ;
                            ns1:landing_value_sprat_SV 2.69072e+03 ;
                            ns1:mean_biomas_sprat 6.483755e+03 ;
                            ns1:mean_biomass_herring 7.392332e+03 ;
                            ns1:repetitions 1 ;
                            ns1:spawning_closure_type 0 ;
                            ns1:spawning_dispersal_rate 4e-02 ;
                            ns1:sprat_price 2.41e+00 ;
                            ns1:stop_herring_growth false ;
                            ns1:ticks 1 ;
                            ns1:trawling_limit "none" ;
                            ns1:winter_closure_length 120 ;
                            ns1:winter_closure_type 1 ;
                            ns1:winter_dispersal_rate 2.7e-02 ;
                            ns1:year_tick 33 ;
                            ns1:yearly_growth_herring 5.2e-01 ] ;
                    sosa:phenomenonTime <file:///github/workspace/model-year-1/month-6/tick-33> ;
                    sosa:resultTime "2026-05-27T00:00:00+00:00"^^xsd:dateTime ;
                    schema:variableMeasured [ dcterms:format "text/plain; delimiter=space; quote=double" ;
                            dcterms:source <file:///github/workspace/> ;
                            schema:numberOfColumns 63 ;
                            schema:numberOfItems 60000 ;
                            ns1:conformsTo "http://www.w3.org/ns/sosa/Observation",
                                "https://docs.ogc.org/is/18-088/18-088.html" ;
                            ns1:regionIndicators [ ns1:nuts_region_01 0 ;
                                    ns1:nuts_region_02 0 ;
                                    ns1:nuts_region_03 0 ;
                                    ns1:nuts_region_04 0 ;
                                    ns1:nuts_region_05 0 ;
                                    ns1:nuts_region_06 0 ;
                                    ns1:nuts_region_07 0 ;
                                    ns1:nuts_region_08 0 ;
                                    ns1:nuts_region_09 0 ;
                                    ns1:nuts_region_10 0 ;
                                    ns1:nuts_region_11 0 ;
                                    ns1:nuts_region_12 0 ;
                                    ns1:nuts_region_13 0 ;
                                    ns1:nuts_region_14 0 ;
                                    ns1:nuts_region_15 0 ;
                                    ns1:nuts_region_16 0 ;
                                    ns1:nuts_region_17 0 ] ;
                            ns1:sourceRow 1 ] ] ;
            sh:resultMessage "sosa:observedProperty is required" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "sosa:observedProperty is required" ;
                    sh:select """
            PREFIX sh: <http://www.w3.org/ns/shacl#>
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (sosa:observedProperty as ?path) (GROUP_CONCAT(?prop; separator=';') AS ?value)
            WHERE {
                OPTIONAL { $this sosa:observedProperty ?prop .
                 $this (sosa:hasResult|sosa:hasSimpleResult) ?result_so_observation }
                OPTIONAL { ?collection (sosa:hasMember|geojson:features)+ $this ; sosa:observedProperty ?prop }
            }
            GROUP BY ?prop
            HAVING (count(?prop) < 1)
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testObservedPropertyPresent> ;
            sh:value "" ] .

